CREATE TABLE IF NOT EXISTS `daily_steps` (`epochDay` INTEGER NOT NULL, `steps` INTEGER NOT NULL, `goal` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`epochDay`));
CREATE TABLE IF NOT EXISTS `walk_sessions` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `startedAt` INTEGER NOT NULL, `endedAt` INTEGER NOT NULL, `steps` INTEGER NOT NULL, `durationSec` INTEGER NOT NULL, `distanceMeters` REAL NOT NULL, `calories` REAL NOT NULL, `pointsEarned` REAL NOT NULL, `track` TEXT NOT NULL, `boostBps` INTEGER NOT NULL, `partySize` INTEGER NOT NULL, `faction` TEXT NOT NULL, `crewId` TEXT NOT NULL, `uploadState` TEXT NOT NULL, `uploadAttemptedAt` INTEGER NOT NULL, `uploadAttempts` INTEGER NOT NULL, `uploadError` TEXT NOT NULL, `verdict` TEXT NOT NULL, `claimSignature` TEXT NOT NULL, `claimSessionHash` TEXT NOT NULL, `claimAmount` TEXT NOT NULL, `claimDay` INTEGER NOT NULL, `claimDeadline` INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS `rewards` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `timestamp` INTEGER NOT NULL, `type` TEXT NOT NULL, `amount` REAL NOT NULL, `description` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `sneakers` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `factionId` TEXT NOT NULL, `rarity` TEXT NOT NULL, `variant` INTEGER NOT NULL, `level` INTEGER NOT NULL, `mintNumber` INTEGER NOT NULL, `luck` REAL NOT NULL, `comfort` REAL NOT NULL, `durability` INTEGER NOT NULL, `equipped` INTEGER NOT NULL, `acquiredAt` INTEGER NOT NULL, `serverId` INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS `boosts` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `type` TEXT NOT NULL, `activatedAt` INTEGER NOT NULL, `expiresAt` INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS `energy_purchases` (`id` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `amount` REAL NOT NULL, `delivered` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `claimed_events` (`eventId` TEXT NOT NULL, `claimedAt` INTEGER NOT NULL, `amount` REAL NOT NULL, PRIMARY KEY(`eventId`));
CREATE TABLE IF NOT EXISTS `crew_memberships` (`crewId` TEXT NOT NULL, `joinedAt` INTEGER NOT NULL, PRIMARY KEY(`crewId`));
CREATE TABLE IF NOT EXISTS `crews` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `monogram` TEXT NOT NULL, `tagline` TEXT NOT NULL, `area` TEXT NOT NULL, `kmAway` REAL NOT NULL, `memberCount` INTEGER NOT NULL, `roster` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `owned` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `posts` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `category` TEXT NOT NULL, `crewId` TEXT NOT NULL, `author` TEXT NOT NULL, `title` TEXT NOT NULL, `body` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `likes` INTEGER NOT NULL, `liked` INTEGER NOT NULL, `commentCount` INTEGER NOT NULL, `mine` INTEGER NOT NULL, `place` TEXT NOT NULL, `distanceKm` REAL NOT NULL, `meetAt` INTEGER NOT NULL, `capacity` INTEGER NOT NULL, `joinedCount` INTEGER NOT NULL, `joined` INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS `comments` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `postId` INTEGER NOT NULL, `parentId` INTEGER NOT NULL, `author` TEXT NOT NULL, `body` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `mine` INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS `courses` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `area` TEXT NOT NULL, `distanceKm` REAL NOT NULL, `elevationM` INTEGER NOT NULL, `track` TEXT NOT NULL, `author` TEXT NOT NULL, `mine` INTEGER NOT NULL, `shared` INTEGER NOT NULL, `likes` INTEGER NOT NULL, `liked` INTEGER NOT NULL, `runCount` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS `notifications` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `timestamp` INTEGER NOT NULL, `type` TEXT NOT NULL, `argText` TEXT NOT NULL, `argAmount` REAL NOT NULL, `argExtra` TEXT NOT NULL, `read` INTEGER NOT NULL, `actioned` INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS `news_items` (`url` TEXT NOT NULL, `title` TEXT NOT NULL, `source` TEXT NOT NULL, `summary` TEXT NOT NULL, `kind` TEXT NOT NULL, `publishedAt` INTEGER NOT NULL, PRIMARY KEY(`url`));
